use moloch_live_runtime::{feedback,package_authority,package_worker,daily_windows};
#[path="../src/package_preflight.rs"]mod package_preflight;
use baal_transport_service::{Scope,Receipt,Endpoint,Permit,multi_leg::{Basket,Leg,Side,Outcome},admission::{BindingLookup,ImmutableBinding}};
use moloch_live_runtime::{package_admission::Admission,package_authority::PackageSnapshotSet,package_not_sent_evidence::VerifiedNotSent};
use moloch_replay::session::Session;
use package_worker::Backend;
use serde_json::{Value,json};
use std::path::Path;
const T:&str="bda92870-621e-47b0-bc3c-3602c5c26f55";
fn at()->u64{daily_windows::clock("2026-10-15T09:01:00Z").unwrap()}
fn iso(t:u64)->String{daily_windows::iso(t).unwrap()}
fn scope(n:usize)->Scope{Scope{tournament_id:T.into(),tournament_slug:"midterm-elections".into(),exchanges:(0..n).map(|i|((101+i).to_string(),(201+i).to_string())).collect()}}
fn basket(n:usize)->Basket{Basket{idempotency_key:"fixture:one".into(),tournament_id:T.into(),maximum_cost:"20.000000".into(),relationship_constraint:None,legs:(0..n).map(|i|Leg{exchange_id:(101+i).to_string(),side:if i==0{Side::No}else{Side::Yes},quantity:10,limit_price:"0.500000".into()}).collect()}}
struct Fixture{scope:Scope,clock:u64,step:u64,reads:Vec<String>,mutate_at:usize,mutation:&'static str,fail_at:usize}
impl Fixture{fn new(n:usize)->Self{Self{scope:scope(n),clock:at(),step:10,reads:vec![],mutate_at:0,mutation:"",fail_at:0}}fn context(&self)->Value{json!({"type":"tournament","tournament":{"id":T},"status":"open"})}}
impl Backend for Fixture{
 fn now_ms(&self)->u64{self.clock}fn scope(&self)->&Scope{&self.scope}fn account_scope(&self)->&str{"fixture-only"}fn evidence_directory(&self)->&Path{Path::new("unused")}
 fn quiet(&self)->feedback::Result<()>{panic!("collector must not request authority")}
 fn lookup(&self,_:&str)->feedback::Result<BindingLookup>{panic!("collector must not inspect write binding")}
 fn prepare(&mut self,_:&Session,_:&Admission,_:Permit,_:PackageSnapshotSet)->feedback::Result<()>{panic!("collector cannot prepare")}
 fn clear_ready(&mut self){panic!("collector cannot change authority")}
 fn send(&mut self,_:Basket,_:Permit)->baal_transport_service::Result<Outcome>{panic!("collector cannot send")}
 fn take_not_sent(&mut self)->feedback::Result<VerifiedNotSent>{panic!("collector cannot take proof")}
 fn retained_not_sent(&mut self,_:&ImmutableBinding,_:&str,_:u64)->feedback::Result<VerifiedNotSent>{panic!("collector cannot mint proof")}
 fn bind_owned(&mut self,_:&str){panic!("collector cannot own orders")}
 fn read(&mut self,ep:Endpoint)->feedback::Result<Receipt>{let start=self.clock;self.clock+=self.step;let (endpoint,data)=match ep{
  Endpoint::Tournament=>(format!("/tournaments/{}",self.scope.tournament_slug),json!({"id":T,"slug":self.scope.tournament_slug,"status":"active","isPendingEnrolment":false,"myBalance":1000,"endDate":iso(at()+600000)})),
  Endpoint::Account=>(format!("/account?tournamentId={T}"),json!({"balance":1000,"availableAdvance":0,"buyingPower":1000})),
  Endpoint::Positions=>(format!("/tournaments/{}/portfolio/positions",self.scope.tournament_slug),json!({"positions":[],"summary":{"totalMarketValue":0,"totalCostBasis":0,"totalUnrealizedPnl":0}})),
  Endpoint::Orders{status}=>{assert_eq!(status,"open");(format!("/orders?status=open&limit=200&tournamentId={T}"),json!({"data":[],"coverage":{"complete":true},"pagination":{"limit":200,"hasMore":false,"nextCursor":null}}))},
  Endpoint::Market{market_id:m}=>{let exchanges:Vec<_>=self.scope.exchanges.iter().filter(|(_,market)|**market==m).map(|(ex,_)|json!({"exchangeId":ex})).collect();(format!("/markets/{m}?tournamentId={T}"),json!({"id":m,"status":"open","isComposite":false,"isMultiOutcome":false,"exchanges":exchanges,"contexts":[self.context()]}))},
  Endpoint::Nodes{market_id:m}=>(format!("/markets/{m}/nodes?tournamentId={T}"),json!({"market_id":m,"contexts":[self.context()],"root":{"node_type":"contract","contract_type":"Election Outcome","node_id":"310","contract_id":"310","opaque":{"refund":"all original data retained"}}})),
  Endpoint::OrderBook{market_id:m,depth}=>{assert_eq!(depth,20);let exchanges:Vec<_>=self.scope.exchanges.iter().filter(|(_,market)|**market==m).map(|(ex,_)|json!({"exchangeId":ex,"asOf":{"at":iso(start),"sequence":17},"bids":[{"price":0.4,"quantity":30}],"asks":[{"price":0.6,"quantity":30}]})).collect();(format!("/markets/{m}/orderbook?tournamentId={T}&depth=20"),json!({"contexts":[{"type":"tournament","tournament":{"id":T},"orderbook":{"exchanges":exchanges}}]}))},
  _=>panic!("unexpected endpoint")};self.reads.push(endpoint.clone());if self.reads.len()==self.fail_at{return Err("actual fixture transport error".into())}let mut r=Receipt{endpoint,status:200,request_started_at:iso(start),received_at:iso(self.clock),data};if self.reads.len()==self.mutate_at{match self.mutation{
   "status"=>r.status=503,"node_missing"=>{r.data["root"].as_object_mut().unwrap().remove("node_id");},"contract_missing"=>{r.data["root"].as_object_mut().unwrap().remove("contract_id");},"both_missing_id_alias"=>{let root=r.data["root"].as_object_mut().unwrap();root.remove("node_id");root.remove("contract_id");root.insert("id".into(),json!("310"));},"node_mismatch"=>r.data["root"]["node_id"]=json!("311"),"contract_numeric"=>r.data["root"]["contract_id"]=json!(310),"node_numeric"=>r.data["root"]["node_id"]=json!(310),"node_empty"=>{r.data["root"]["node_id"]=json!("");r.data["root"]["contract_id"]=json!("");},"noncontract"=>r.data["root"]["node_type"]=json!("predicate"),"oldorder"=>r.request_started_at=iso(at()),"position"=>r.data["positions"]=json!([{"exchangeId":"999","marketId":"999","quantity":0}]),"endpoint"=>r.endpoint.push_str("&foreign=1"),"future"=>r.received_at=iso(self.clock+1),"reversed"=>r.request_started_at=iso(self.clock+1),"partial"=>r.data["coverage"]["complete"]=json!(false),"pagination"=>r.data["pagination"]["hasMore"]=json!(true),"rule"=>r.data["root"]["opaque"]["refund"]=json!("changed"),"scope"=>r.data["contexts"][0]["tournament"]["id"]=json!("foreign"),"bookmissing"=>r.data["contexts"][0]["orderbook"]["exchanges"]=json!([]),"bookclock"=>r.data["contexts"][0]["orderbook"]["exchanges"][0]["asOf"]["at"]=json!(iso(start+1000)),"slowcohort"=>self.clock+=21000,"stale_book"=>r.data["contexts"][0]["orderbook"]["exchanges"][0]["asOf"]["at"]=json!(iso(start-10001)),_=>panic!("bad mutation")}}Ok(r)
 }
}
#[test]fn two_components_exact_ten_reads_in_order_with_every_original_receipt_callback(){let mut f=Fixture::new(2);let s=f.scope.clone();let mut seen=vec![];let facts=package_preflight::collect(&mut f,&s,&basket(2),|r|{seen.push(serde_json::to_value(r)?);Ok(())}).unwrap();assert_eq!(f.reads.len(),10);assert_eq!(seen.len(),10);assert_eq!(f.reads[0],"/tournaments/midterm-elections");assert!(f.reads[3].starts_with("/orders?status=open"));assert!(f.reads[4].starts_with("/markets/201?"));assert!(f.reads[9].contains("/202/orderbook?"));assert_eq!(facts.components.len(),2);assert_eq!(seen[5]["data"],facts.components["101"].contract.data);assert_eq!(facts.components["101"].contract.data["root"]["opaque"]["refund"],"all original data retained");}
#[test]fn three_components_exact_thirteen_reads_no_extra_clients_or_retries(){let mut f=Fixture::new(3);let s=f.scope.clone();let mut calls=0;let facts=package_preflight::collect(&mut f,&s,&basket(3),|_|{calls+=1;Ok(())}).unwrap();assert_eq!(f.reads.len(),13);assert_eq!(calls,13);assert_eq!(facts.components.len(),3);}
#[test]fn invalid_configuration_never_performs_a_read(){for kind in ["duplicate","foreign","zero","price","count","tournament","slug"]{let mut f=Fixture::new(2);let mut s=f.scope.clone();let mut b=basket(2);match kind{"duplicate"=>b.legs[1].exchange_id="101".into(),"foreign"=>b.legs[0].exchange_id="999".into(),"zero"=>b.legs[0].quantity=0,"price"=>b.legs[0].limit_price="0.501000".into(),"count"=>{b.legs.pop();},"tournament"=>b.tournament_id="foreign".into(),_=>s.tournament_slug="../foreign".into()};assert!(package_preflight::collect(&mut f,&s,&b,|_|Ok(())).is_err(),"{kind}");assert!(f.reads.is_empty(),"{kind}");}}
#[test]fn callback_abort_after_each_global_or_component_read_stops_next_read(){for cut in 1..=10{let mut f=Fixture::new(2);let s=f.scope.clone();let mut seen=0;assert!(package_preflight::collect(&mut f,&s,&basket(2),|_|{seen+=1;if seen==cut{Err("STOP/control/source admission failed".into())}else{Ok(())}}).is_err());assert_eq!(f.reads.len(),cut);assert_eq!(seen,cut);}}
#[test]fn actual_transport_error_has_no_fabricated_receipt_or_callback(){let mut f=Fixture::new(2);f.fail_at=6;let s=f.scope.clone();let mut seen=0;assert!(package_preflight::collect(&mut f,&s,&basket(2),|_|{seen+=1;Ok(())}).is_err());assert_eq!(f.reads.len(),6);assert_eq!(seen,5);}
#[test]fn actual_bad_receipt_is_observed_once_then_fails_before_next_read(){for (index,why) in [(1,"status"),(5,"endpoint"),(2,"future"),(3,"reversed"),(4,"partial"),(4,"pagination"),(6,"scope"),(7,"bookmissing"),(7,"bookclock"),(7,"stale_book"),(3,"position"),(5,"oldorder")]{let mut f=Fixture::new(2);f.mutate_at=index;f.mutation=why;let s=f.scope.clone();let mut seen=0;assert!(package_preflight::collect(&mut f,&s,&basket(2),|_|{seen+=1;Ok(())}).is_err(),"{why}");assert_eq!(f.reads.len(),index,"{why}");assert_eq!(seen,index,"{why}");}}
#[test]fn slow_complete_cohort_cannot_return_stale_initial_account_facts(){let mut f=Fixture::new(2);f.mutate_at=10;f.mutation="slowcohort";let s=f.scope.clone();assert!(package_preflight::collect(&mut f,&s,&basket(2),|_|Ok(())).is_err());assert_eq!(f.reads.len(),10);}
#[test]fn changed_opaque_rule_can_be_rejected_by_source_bound_callback_without_another_read(){let mut f=Fixture::new(2);f.mutate_at=6;f.mutation="rule";let s=f.scope.clone();assert!(package_preflight::collect(&mut f,&s,&basket(2),|r|{if r.endpoint.contains("/nodes?")&&r.data["root"]["opaque"]["refund"]!="all original data retained"{Err("reviewed contract body changed".into())}else{Ok(())}}).is_err());assert_eq!(f.reads.len(),6);}
#[test]fn collector_does_not_invent_rule_approval_when_caller_supplies_no_certificate(){let mut f=Fixture::new(2);f.mutate_at=6;f.mutation="rule";let s=f.scope.clone();let facts=package_preflight::collect(&mut f,&s,&basket(2),|_|Ok(())).unwrap();assert_eq!(facts.components["101"].contract.data["root"]["opaque"]["refund"],"changed");/* Returned facts alone cannot construct Admission or authorize a send. */}
#[test]fn individually_fresh_receipts_cannot_hide_an_expired_whole_account_cohort(){let mut f=Fixture::new(3);f.step=2000;let s=f.scope.clone();assert!(package_preflight::collect(&mut f,&s,&basket(3),|_|Ok(())).err().unwrap().to_string().contains("RECEIPT_CLOCK_OR_STATUS"));assert_eq!(f.reads.len(),13);}
#[test]fn component_receipts_must_remain_ten_second_fresh_at_return_even_if_globals_fit_twenty(){let mut f=Fixture::new(3);f.step=1500;let s=f.scope.clone();assert!(package_preflight::collect(&mut f,&s,&basket(3),|_|Ok(())).is_err());assert_eq!(f.reads.len(),13);assert!(f.clock-at()<20000);}
#[test]fn actual_official_string_node_and_contract_ids_work_without_root_id_alias(){let mut f=Fixture::new(2);let s=f.scope.clone();let facts=package_preflight::collect(&mut f,&s,&basket(2),|_|Ok(())).unwrap();let root=&facts.components["101"].contract.data["root"];assert_eq!(root["node_type"],"contract");assert_eq!(root["node_id"],"310");assert_eq!(root["contract_id"],"310");assert!(root.get("id").is_none());assert_eq!(f.reads.len(),10);}
#[test]fn mismatched_missing_empty_or_nonstring_contract_identity_denies_immediately(){for mutation in ["node_missing","contract_missing","both_missing_id_alias","node_mismatch","contract_numeric","node_numeric","node_empty","noncontract"]{let mut f=Fixture::new(2);f.mutate_at=6;f.mutation=mutation;let s=f.scope.clone();let mut observed=0;assert!(package_preflight::collect(&mut f,&s,&basket(2),|_|{observed+=1;Ok(())}).is_err(),"{mutation}");assert_eq!(f.reads.len(),6,"{mutation}");assert_eq!(observed,6,"{mutation}");}}
